/* eslint-disable jsx-a11y/anchor-is-valid */
/* eslint-disable no-lone-blocks */
import React, { Component } from 'react';
import {Table, Card,Tabs} from 'antd'; 
import { withRouter } from 'react-router-dom';

const { TabPane } = Tabs;
function callback(key) {
	console.log(key);
  }
class Orders extends Component {	
	constructor(props){
		super(props)
	this.state = {orders:[]};

	this.viewCoin = ()=> {
		props.history.push("/viewcoins");
	  };

    // this.getCryptoData = async ()=> {

	//  let data = await CryptoCoinsOnDashboard();
	// 	  this.setState({
	// 		cryptodata:data
	// 	  });


	//  };

	this.otherpage=(text)=>{

		 this.props.history.push({
			pathname: '/viewcoin',
			coin: text,
		  });
	 };
	}   

	componentDidMount() {

		// this.getCryptoData();


		// this.intervalID=setInterval(this.getCryptoData.bind(this),5000)
	  }

    componentWillUnmount() {
		// clearInterval(this.intervalID);
	  }

	render() {  
		const total = this.state.orders.length;
	const columns = [
		{
			title: 'Date',
			dataIndex: 'createdAt',
			key: 'createdAt',
            render: text => <a style={{color:'#555555'}}>{text}</a>,

		  },
		{
			title: 'Customer Name',
			dataIndex: 'name',
			key: 'name',

			render: (text) => (
				<span>
				<a style={{color:'green'}} onClick={()=>this.otherpage(text)}> {text}</a>

				</span>
			),
			},
			{
			title: 'Product',
			dataIndex: 'product',
			key: 'product',
			render: text => <a style={{color:'#555555'}}>{text}</a>,
			},
			{
			title: 'Phone Number',
			dataIndex: 'phone',
			key: 'phone',
			render: text => {{
				let color = text > 0 ? 'green' : 'red' 
		       return(
			   <a style={{color:color}}>  ${text.toLocaleString(navigator.language, { minimumFractionDigits: 2 })}</a>
			   )}
		       },             

			},
			{
				title: 'Volume 24 Hour',
				dataIndex:'volume24hour',
				key: 'volume24hour',
				render: text =><a style={{color:'#555555'}}>{text}</a> 	
			},
			{
			title: 'Market Capitalisation',
			dataIndex:'marketevariation',
			key: 'marketevariation',
			render: text =><a style={{color:'#555555'}}>{text}</a> 	
		},			  
		];
		return (
	<div>
	<Tabs defaultActiveKey="1" onChange={callback}>
	 <TabPane tab="All coins" key="1">
                <Card title="All Coins List"  bodyStyle={{padding:0}} loading={false}>
					<div className="table-responsive">
					<Table columns={columns} dataSource={this.state.orders} limit={10} onPress={()=>this.viewCoin()} pagination={{size:'small', total:total, showTotal:total => `Total ${total} Coins`}}  />
					</div>
				</Card>
		</TabPane>
		<TabPane tab="Toplist by 24H Volume " key="2">

		</TabPane>
	</Tabs>
	</div>
		);
	}
}
export default withRouter(Orders);
